update public.pooja_steps set instruction_ta = 'கிழக்கு அல்லது வடக்கு நோக்கி அமரவும். வலது கையின் ஆட்காட்டி விரலை கட்டைவிரலுடன் சேர்த்து, மற்ற மூன்று விரல்களையும் மடக்கி உள்ளங்கையில் ஒரு உத்தரிணி நீர் நிற்குமாறு வைக்கவும். மூன்று நாமங்களிலும் ஒவ்வொரு முறை நீரை உள்கொள்ளவும். ஆசமனமும் அங்கவந்தனமும் தொடக்கத்தில் மும்முறை செய்யப்படும்.', updated_at = now()
