update public.pooja_steps set instruction_ta = 'ஆட்காட்டி, நடுவிரல்களை மடக்கவும். வலது நாசியைக் கட்டைவிரலாலும், இடது நாசியை மோதிர, சுண்டு விரல்களாலும் அடைக்கவும். மந்திரம் மூன்று பகுதிகள்: இடது நாசி வழியாக மூச்சை இழுத்தபடி "ஓம் பூஃ" முதல் "ஓகும் ஸத்யம்" வரை; மூச்சை நிறுத்தி "ஓம் தத் ஸவிதுஃ" முதல் "ப்ரசோதயாத்" வரை; வலது நாசி வழியாக வெளியிட்டபடி "ஓம் ஆபோ ஜ்யோதி" முதல் "பூர்புவஸ்ஸுவரோம்" வரை. இதுவே ஒரு ப்ராணாயாமம்.', updated_at = now()
