 where pooja_id = 'sandhyavandanam' and step_title_en = 'Jala Prarthana';
update public.pooja_steps set instruction_ta = 'முதல் ஏழு வரிகளிலும் மோதிர விரலால் தலையில் நீர் தெளிக்கவும். எட்டாவது வரியில் வலது, இடது தொடைகளைத் தொடவும். ஒன்பதாவது வரியில் மீண்டும் தெளிக்கவும். பின் வலது உள்ளங்கையில் நீர் எடுத்து தலையைச் சுற்றி வலமாகச் சுழற்றவும்.', updated_at = now()
