update public.pooja_steps set instruction_ta = 'இரு உள்ளங்கைகளிலும் நீர் ஏந்தி, மந்திரம் முடியும்போது விரல் நுனிகள் வழியே கீழே விடவும். காலையிலும் மாலையிலும் மூன்று முறை; உச்சிப்போதில் இரண்டு முறை. பின் ஒரு ப்ராணாயாமம்.', updated_at = now()
 where pooja_id = 'sandhyavandanam' and step_title_en = 'Arghya Pradanam';
update public.pooja_steps set instruction_ta = 'ஸங்கல்பத்தில் செய்தது போல கைகளை வைத்துச் சொல்லவும். பின் மீண்டும் ஒரு முறை அர்க்யம் கொடுத்து, இறுதி வரியைச் சொல்லியபடி தலையைச் சுற்றி நீர் சுழற்றவும்.', updated_at = now()
