insert into public.archana_items
  (pooja_step_id, seq, invoked_name_deva, invoked_name_ta, invoked_name_translit, offering_en)
select id, 4, 'सरस्वत्यै नमः', 'ஸரஸ்வத்யை நம꞉', 'sarasvatyai namaḥ', 'North'
  from public.pooja_steps where pooja_id = 'sandhyavandanam' and step_number = 38;
insert into public.archana_items
  (pooja_step_id, seq, invoked_name_deva, invoked_name_ta, invoked_name_translit, offering_en)
select id, 5, 'सर्वाभ्यो देवताभ्यो नमः।', 'ஸர்வாப்யோ தேவதாப்யோ நம꞉।', 'sarvābhyo devatābhyo namaḥ।', 'East'
  from public.pooja_steps where pooja_id = 'sandhyavandanam' and step_number = 38;

-- 39. Abhivadanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('sandhyavandanam', 39, 'pradhana', 'Abhivadanam', 'அபிவாதனம்',
   'Cover both ears with the hands and touch the floor at the end. Say your own pravara rishis, gotra and name in the blanks — the book leaves them blank because the reciter knows them. Three rishis take tryarsheya, five take panchaarsheya.',
   'இரு காதுகளையும் கைகளால் மூடி, இறுதியில் தரையைத் தொடவும். இடைவெளிகளில் உங்கள் ப்ரவர ரிஷிகள், கோத்ரம், பெயர் ஆகியவற்றைச் சொல்லவும் — சொல்பவருக்குத் தெரியும் என்பதால் நூலும் அவற்றை வெறுமையாகவே விட்டிருக்கிறது. மூன்று ரிஷிகளானால் த்ர்யார்ஷேய, ஐந்தானால் பஞ்சார்ஷேய.',
   'अभिवादये ............ ............ ............ ............ ............
त्र्यार्षेय / पञ्चार्षेय प्रवरान्वित ............ गोत्रः आपस्तम्ब सूत्रः
यजुः शाखाऽध्यायी श्री ............ शर्मा नामाहं अस्मि भोः',
   'அபிவாதயே ............ ............ ............ ............ ............
த்ர்யார்ஷேய / பஞ்சார்ஷேய ப்ரவராந்வித ............ கோத்ர꞉ ஆபஸ்தம்ப ஸூத்ர꞉
யஜு꞉ ஶாகாத்யாயீ ஶ்ரீ ............ ஶர்மா நாமாஹம் அஸ்மி போ꞉',
   'abhivādaye ............ ............ ............ ............ ............
tryārṣeya / pañcārṣeya pravarānvita ............ gotraḥ āpastamba sūtraḥ
yajuḥ śākhā''dhyāyī śrī ............ śarmā nāmāhaṃ asmi bhoḥ',
   'I salute — of the pravara of three (or five) rishis, of such a gotra, of the Apastamba sutra, a student of the Yajus recension: I am so-and-so sharma by name, sir.',
   'Printed with its blanks, as the book prints it. The book fills in two of the five slots in type — Apastamba sutra and the Yajus recension, because it is a Yajurveda Apastamba manual — and leaves the rest dotted. The ears are covered because the reciter is about to say his own name and lineage aloud.',
   array['pratah', 'madhyahnika', 'sayam']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.28-48, photographed page');

-- 40. Dig Devata Vandanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('sandhyavandanam', 40, 'pradhana', 'Dig Devata Vandanam', 'திக் தேவதா வந்தனம்',
   'Salute each quarter as it is named. The last three — above, below and the mid-space — are said facing east without turning.',
   'ஒவ்வொரு திசையையும் சொல்லும்போது வணங்கவும். இறுதி மூன்று — மேல், கீழ், அந்தரிக்ஷம் — திரும்பாமல் கிழக்கு நோக்கியே சொல்லப்படும்.',
   null,
   null,
   null,
   'Salutation to the eastern quarter, the southern, the western, the northern; to what is above, what is below, and the space between; to Earth, to Brahma, to Vishnu, to Death.',
   'The Samashti Abhivadanam turned through four quarters; this salutes the quarters as deities in their own right and then adds the vertical — up, down, and the space between — without turning. Eleven salutations, four horizontal, three vertical and four by name.',
   array['pratah', 'madhyahnika', 'sayam']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.28-48, photographed page');

