-- 41. Yama Vandanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('sandhyavandanam', 41, 'pradhana', 'Yama Vandanam', 'யம வந்தனம்',
   'Face south while reciting.',
   'தெற்கு நோக்கிச் சொல்லவும்.',
   'यमाय नमः
यमाय धर्मराजाय मृत्यवे चान्तकाय च।
वैवस्वताय कालाय सर्वभूतक्षयाय च॥
औदुम्बराय दध्नाय नीलाय परमेष्ठिने।
वृकोदराय चित्राय चित्रगुप्ताय वै नमः॥
''चित्र गुप्ताय वै नम ओं नमः'' इति',
   'யமாய நம꞉
யமாய தர்மராஜாய ம்ருத்யவே சாந்தகாய ச।
வைவஸ்வதாய காலாய ஸர்வபூதக்ஷயாய ச॥
ஔதும்பராய தத்நாய நீலாய பரமேஷ்டிநே।
வ்ருகோதராய சித்ராய சித்ரகுப்தாய வை நம꞉॥
சித்ர குப்தாய வை நம ஓம் நம꞉ இதி',
   'yamāya namaḥ
yamāya dharmarājāya mṛtyave cāntakāya ca।
vaivasvatāya kālāya sarvabhūtakṣayāya ca॥
audumbarāya dadhnāya nīlāya parameṣṭhine।
vṛkodarāya citrāya citraguptāya vai namaḥ॥
''citra guptāya vai nama oṃ namaḥ'' iti',
   'Salutation to Yama, to the king of dharma, to Death and to the Ender; to the son of Vivasvat, to Time, to the destroyer of all beings; to the one of the udumbara, to Dadhna, to the dark one, to the highest; to the wide-bellied, to Chitra, and to Chitragupta.',
   'Twelve datives, and the rite that began by asking Mitra for protection ends by naming death in every aspect it has. The last name is Chitragupta, said again on its own — the one who writes down what each person did. After three confessions, the rite bows to the clerk who keeps the account.',
   array['pratah', 'madhyahnika', 'sayam']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.28-48, photographed page');

-- 42. Harihara Vandanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('sandhyavandanam', 42, 'pradhana', 'Harihara Vandanam', 'ஹரிஹர வந்தனம்',
   'Face north while reciting.',
   'வடக்கு நோக்கிச் சொல்லவும்.',
   'ऋतꣳसत्यं परं ब्रह्म पुरुषं कृष्णपिङ्गलम्।
ऊर्ध्वरेतं विरूपाक्षं विश्वरूपाय वै नमो नमः॥
''विश्वरूपाय वै नम ओं नम इति''',
   'ருதகும்ஸத்யம் பரம் ப்ரஹ்ம புருஷம் க்ருஷ்ணபிங்கலம்।
ஊர்த்வரேதம் விரூபாக்ஷம் விஶ்வரூபாய வை நமோ நம꞉॥
விஶ்வரூபாய வை நம ஓம் நம இதி',
   'ṛtagmsatyaṃ paraṃ brahma puruṣaṃ kṛṣṇapiṅgalam।
ūrdhvaretaṃ virūpākṣaṃ viśvarūpāya vai namo namaḥ॥
''viśvarūpāya vai nama oṃ nama iti''',
   'Order and truth, the supreme Brahman, the person dark and tawny, whose seed is drawn upward, of strange eyes — salutation, salutation to him whose form is the universe.',
   'One figure, not two. Dark and tawny is the whole point: the grey body of Vishnu blended with the red of Shiva in a single form. It makes the same case in one word that the panchayatana arrangement makes with five deities and a diagram.',
   array['pratah', 'madhyahnika', 'sayam']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.28-48, photographed page');

-- 43. Suryanarayana Vandanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('sandhyavandanam', 43, 'pradhana', 'Suryanarayana Vandanam', 'ஸூர்யநாராயண வந்தனம்',
   'Face east while reciting.',
   'கிழக்கு நோக்கிச் சொல்லவும்.',
   'नमः सवित्रे जगदेकचक्षुषे जगत्प्रसूतिस्थितिनाशहेतवे।
त्रयीमयाय त्रिगुणात्मधारिणे विरिञ्चिनारायणशङ्करात्मने॥ १
ध्येयः सदा सवितृमण्डलमध्यवर्ती नारायणः सरसिजासनसंनिविष्टः।
केयूरवान् मकरकुण्डलवान् किरीटी हारी हिरण्मयवपुर्धृतशङ्खचक्रः॥ २
शङ्खचक्रगदापाणे द्वारकानिलयाच्युत।
गोविन्द पुण्डरीकाक्ष रक्ष मां शरणागतम्॥ ३
आकाशात् पतितं तोयं यथा गच्छति सागरम्।
सर्वदेवनमस्कारः केशवं प्रति गच्छति॥ ४
श्रीकेशवं प्रति गच्छत्यों नम इति',
   'நம꞉ ஸவித்ரே ஜகதேகசக்ஷுஷே ஜகத்ப்ரஸூதிஸ்திதிநாஶஹேதவே।
த்ரயீமயாய த்ரிகுணாத்மதாரிணே விரிஞ்சிநாராயணஶங்கராத்மநே॥ ௧
த்யேய꞉ ஸதா ஸவித்ருமண்டலமத்யவர்தீ நாராயண꞉ ஸரஸிஜாஸநஸம்நிவிஷ்ட꞉।
கேயூரவாந் மகரகுண்டலவாந் கிரீடீ ஹாரீ ஹிரண்மயவபுர்த்ருதஶங்கசக்ர꞉॥ ௨
ஶங்கசக்ரகதாபாணே த்வாரகாநிலயாச்யுத।
கோவிந்த புண்டரீகாக்ஷ ரக்ஷ மாம் ஶரணாகதம்॥ ௩
ஆகாஶாத் பதிதம் தோயம் யதா கச்சதி ஸாகரம்।
ஸர்வதேவநமஸ்கார꞉ கேஶவம் ப்ரதி கச்சதி॥ ௪
ஶ்ரீகேஶவம் ப்ரதி கச்சத்யோம் நம இதி',
   'namaḥ savitre jagadekacakṣuṣe jagatprasūtisthitināśahetave।
trayīmayāya triguṇātmadhāriṇe viriñcinārāyaṇaśaṅkarātmane॥ 1
dhyeyaḥ sadā savitṛmaṇḍalamadhyavartī nārāyaṇaḥ sarasijāsanasaṃniviṣṭaḥ।
keyūravān makarakuṇḍalavān kirīṭī hārī hiraṇmayavapurdhṛtaśaṅkhacakraḥ॥ 2
śaṅkhacakragadāpāṇe dvārakānilayācyuta।
govinda puṇḍarīkākṣa rakṣa māṃ śaraṇāgatam॥ 3
ākāśāt patitaṃ toyaṃ yathā gacchati sāgaram।
sarvadevanamaskāraḥ keśavaṃ prati gacchati॥ 4
śrīkeśavaṃ prati gacchatyoṃ nama iti',
   'Salutation to Savitr, the one eye of the world, cause of its birth, its standing and its end; made of the three Vedas, bearing the three qualities, whose self is Brahma, Vishnu and Shankara. Narayana seated always in the middle of the solar orbit, on the lotus, with armlets and makara earrings, crowned and garlanded, golden-bodied, holding conch and discus, is ever worthy of meditation. Holder of conch, discus and mace, dweller in Dvaraka, Achyuta, Govinda, lotus-eyed — protect me, who have come for refuge. As water fallen from the sky makes its way to the sea, salutation to any god makes its way to Keshava.',
   'The closing verse is the rite''s own justification. After Mitra, Varuna, nine planets, twelve months, four quarters, three verticals and the lord of death, it says all of it arrives at one place. It also answers the question a reader is most likely to have by now — why so many names — and it answers it with water finding the sea.',
   array['pratah', 'madhyahnika', 'sayam']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.28-48, photographed page');

-- 44. Samarpanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('sandhyavandanam', 44, 'pradhana', 'Samarpanam', 'ஸமர்ப்பணம்',
   'Cover both ears with the hands again, say the Abhivadanam once more, and touch the floor and prostrate at the end.',
   'மீண்டும் இரு காதுகளையும் கைகளால் மூடி, அபிவாதனத்தை ஒரு முறை சொல்லி, இறுதியில் தரையைத் தொட்டு நமஸ்கரிக்கவும்.',
   'अभिवादये..... अस्मि भोः
कायेन वाचा मनसेन्द्रियैर्वा बुध्याऽऽत्मना वा प्रकृतेः स्वभावात्।
करोमि यद्यत् सकलं परस्मै नारायणायेति समर्पयामि॥
मन्त्रहीनं क्रियाहीनं भक्तिहीनं जनार्दन।
यत् कृतं तु मया देव परिपूर्णं तदस्तु ते॥
प्रायश्चित्तान्यशेषाणि तपःकर्मात्मकानि वै।
यानि तेषामशेषाणां श्री कृष्णानुस्मरणं परम्॥
श्री कृष्ण कृष्ण कृष्ण',
   'அபிவாதயே..... அஸ்மி போ꞉
காயேந வாசா மநஸேந்த்ரியைர்வா புத்யாத்மநா வா ப்ரக்ருதே꞉ ஸ்வபாவாத்।
கரோமி யத்யத் ஸகலம் பரஸ்மை நாராயணாயேதி ஸமர்பயாமி॥
மந்த்ரஹீநம் க்ரியாஹீநம் பக்திஹீநம் ஜநார்தந।
யத் க்ருதம் து மயா தேவ பரிபூர்ணம் ததஸ்து தே॥
ப்ராயஶ்சித்தாந்யஶேஷாணி தப꞉கர்மாத்மகாநி வை।
யாநி தேஷாமஶேஷாணாம் ஶ்ரீ க்ருஷ்ணாநுஸ்மரணம் பரம்॥
ஶ்ரீ க்ருஷ்ண க்ருஷ்ண க்ருஷ்ண',
   'abhivādaye..... asmi bhoḥ
kāyena vācā manasendriyairvā budhyā''''tmanā vā prakṛteḥ svabhāvāt।
karomi yadyat sakalaṃ parasmai nārāyaṇāyeti samarpayāmi॥
mantrahīnaṃ kriyāhīnaṃ bhaktihīnaṃ janārdana।
yat kṛtaṃ tu mayā deva paripūrṇaṃ tadastu te॥
prāyaścittānyaśeṣāṇi tapaḥkarmātmakāni vai।
yāni teṣāmaśeṣāṇāṃ śrī kṛṣṇānusmaraṇaṃ param॥
śrī kṛṣṇa kṛṣṇa kṛṣṇa',
   'Whatever I do by body, speech, mind, senses, intellect, self or by the force of nature, all of it I offer to the supreme Narayana. Short of mantra, short of rite, short of devotion, Janardana — whatever I have done, let it stand complete for you. Of all expiations whatsoever, made of austerity and action, the remembrance of Krishna is the highest.',
   'The app already holds two of these three verses: kaayena vaachaa, and the mantra-heenam that closes the Ganesha pooja. Completion is asked for as something the deity grants, not something the karta achieved. The third verse is new and it outranks everything before it: of all the expiations in a rite full of them, remembering a name is the highest.',
   array['pratah', 'madhyahnika', 'sayam']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.28-48, photographed page');

-- 45. Japasthanam Prokshanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('sandhyavandanam', 45, 'pradhana', 'Japasthanam Prokshanam', 'ஜபஸ்தான ப்ரோக்ஷணம்',
   'Do Achamanam and Anga Vandanam once. Then take water in the hand, pour it down at the end of the mantra, and make a tilak with it. Finally pour water onto the plate as an offering while saying the closing line.',
   'ஆசமனமும் அங்கவந்தனமும் ஒரு முறை செய்யவும். பின் கையில் நீர் எடுத்து, மந்திரம் முடியும்போது கீழே விட்டு, அந்த நீரால் திலகம் இடவும். இறுதியாக, இறுதி வரியைச் சொல்லியபடி தாம்பாளத்தில் நீரை அர்ப்பணமாக விடவும்.',
   'अद्या नो देव सवितः। प्रजावत्सावीः सौभगम्। परा दुष्वप्नियꣳसुव।
विश्वानि देव सवितः। दुरितानि परासुव। यद् भद्रं तन्म आसुव॥
''ओं तत् सत् ब्रह्मार्पणमस्तु''',
   'அத்யா நோ தேவ ஸவித꞉। ப்ரஜாவத்ஸாவீ꞉ ஸௌபகம்। பரா துஷ்வப்நியகும்ஸுவ।
விஶ்வாநி தேவ ஸவித꞉। துரிதாநி பராஸுவ। யத் பத்ரம் தந்ம ஆஸுவ॥
ஓம் தத் ஸத் ப்ரஹ்மார்பணமஸ்து',
   'adyā no deva savitaḥ। prajāvatsāvīḥ saubhagam। parā duṣvapniyagmsuva।
viśvāni deva savitaḥ। duritāni parāsuva। yad bhadraṃ tanma āsuva॥
''oṃ tat sat brahmārpaṇamastu''',
   'Today, god Savitr, send us prosperity with children. Drive away the bad dream. God Savitr, drive away all our wrongs, and send us what is good. Om tat sat — let it be an offering to Brahman.',
   'The rite ends by sealing the PLACE rather than the person: water is poured where the reciter has been sitting. And the last request is for sleep — drive away the bad dream. After the planets, the months, the directions, death and the keeper of the record, the closing mantra asks for children, for nightmares to stop, and for whatever is good. It is the plainest sentence in the rite.',
   array['pratah', 'madhyahnika', 'sayam']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.28-48, photographed page');

-- The rite is whole. Publish it.
update public.poojas set status = 'published', updated_at = now() where id = 'sandhyavandanam';

-- --- assert ------------------------------------------------------------------
do $$
declare n int;
begin
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam';
  if n <> 45 then raise exception 'expected 45 steps, found %', n; end if;

  select count(*) into n from (
    select step_number, row_number() over (order by step_number) as rn
      from public.pooja_steps where pooja_id = 'sandhyavandanam'
  ) t where t.step_number <> t.rn;
  if n > 0 then raise exception '% step(s) are not numbered 1..n', n; end if;

  -- EVERY step has Tamil now, part one included. This is the assertion 0048
  -- should have carried.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'sandhyavandanam' and coalesce(trim(instruction_ta), '') = '';
  if n > 0 then raise exception '% step(s) still have no Tamil instruction', n; end if;
  select count(*) into n from public.pooja_steps
   where pooja_id = 'sandhyavandanam' and instruction_ta !~ '[஀-௿]';
  if n > 0 then raise exception '% Tamil instruction(s) carry no Tamil', n; end if;

  -- Every sitting walks the whole rite.
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam' and 'pratah' = any(modes);
  if n <> 35 then raise exception 'pratah has % steps, expected 35', n; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam' and 'madhyahnika' = any(modes);
  if n <> 35 then raise exception 'madhyahnika has % steps, expected 35', n; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam' and 'sayam' = any(modes);
  if n <> 35 then raise exception 'sayam has % steps, expected 35', n; end if;

  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam' and mantra_sanskrit like '%सायं मन्ध्या गायत्री%';
  if n > 0 then raise exception '% step(s) still carry the misprint सायं मन्ध्या गायत्री', n; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam' and mantra_sanskrit like '%सायं सन्ध्या गायत्री%';
  if n < 1 then raise exception 'the correction सायं सन्ध्या गायत्री is not present'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam' and mantra_sanskrit like '%भूरादिससव्याहृतीनाम्%';
  if n > 0 then raise exception '% step(s) still carry the misprint भूरादिससव्याहृतीनाम्', n; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam' and mantra_sanskrit like '%भूरादिसप्तव्याहृतीनाम्%';
  if n < 1 then raise exception 'the correction भूरादिसप्तव्याहृतीनाम् is not present'; end if;

  -- Dandas stripped: they belong in Tamil mantras. See 0048.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'sandhyavandanam'
     and translate(coalesce(mantra_tamil, ''), '।॥', '') ~ '[ऀ-ॿ꣠-ꣿ]';
  if n > 0 then raise exception '% Tamil mantra(s) carry Devanagari', n; end if;

  -- Published, and the planned-with-steps gate is satisfied.
  select count(*) into n from public.poojas where id = 'sandhyavandanam' and status = 'published';
  if n <> 1 then raise exception 'sandhyavandanam was not published'; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;
